    paths = {}
    def query(name, typ='string', required=False):
        return {'name':name,'in':'query','required':required,'schema':{'type':typ}}
    def add(path, method, operation, response=None, body=None, parameters=None, status='200'):
        item = {'operationId': operation, 'responses': {status: {'description':'Success','content':{'application/json':{'schema':ref(response) if response else {'type':'object'}}}}}}
        for code, text in [('400','Invalid request'),('403','Untrusted origin'),('404','Not found'),('405','Method not allowed'),('409','Version/capacity conflict'),('503','Runtime unavailable')]:
            item['responses'][code]={'description':text,'content':{'application/json':{'schema':ref('Error')}}}
        params = list(parameters or [])
        for part in path.split('/'):
            if part.startswith('{'):
                params.append({'name':part[1:-1],'in':'path','required':True,'schema':{'type':'string'}})
        if params:item['parameters']=params
        if body:item['requestBody']={'required':True,'content':{'application/json':{'schema':ref(body) if body in schemas else {'type':'object'}}}}
        paths.setdefault(path,{})[method]=item
